function split_evenly(total, parts)
    each = total ÷ parts
    rest = total - each * parts
    @assert 0 <= rest < parts
    return fill(each, parts) .+ [i <= rest ? 1 : 0 for i in 1:parts]
end
println(split_evenly(10, 3))
@assert 1 + 1 == 3

