using Test
xs = [3, 1, 2]
@test sort(xs) == [1, 2, 4]

using Test
struct Countdown
    from::Int
end
Base.iterate(c::Countdown, n = c.from) = n < 1 ? nothing : (n, n - 1)
Base.length(c::Countdown) = max(c.from, 0)
Base.eltype(::Type{Countdown}) = Int

@testset "Countdown iteration" begin
    @test collect(Countdown(3)) == [3, 2, 1]
    @test isempty(collect(Countdown(0)))
    @test length(Countdown(4)) == length(collect(Countdown(4)))
    @test eltype(collect(Countdown(2))) == Int
    @test sum(Countdown(4)) == 10
end;

