function chunked_sum(xs; ntasks = 4)
    len = cld(length(xs), ntasks)
    tasks = [Threads.@spawn sum(chunk) for chunk in Iterators.partition(xs, len)]
    return sum(fetch, tasks)
end
chunked_sum(1:1_000_000)

